import{_ as a,o as e,c as d,a6 as o}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"Amazon主图与副图：一步一步制作","description":"","frontmatter":{"id":"amazon-listing","title":"Amazon主图与副图：一步一步制作","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","rembg","birefnet","ecommerce-image-toolkit","visual-copywriting"],"platform_rule_ids":["amazon"],"order":23.1,"content_kind":"操作教程"},"headers":[],"relativePath":"ecommerce/amazon-listing.md","filePath":"ecommerce/amazon-listing.md"}'),s={name:"ecommerce/amazon-listing.md"};function i(r,t,n,l,p,c){return e(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="amazon主图与副图-从实拍做到可交付文件" tabindex="-1">Amazon主图与副图，从实拍做到可交付文件 <a class="header-anchor" href="#amazon主图与副图-从实拍做到可交付文件" aria-label="Permalink to &quot;Amazon主图与副图，从实拍做到可交付文件&quot;">​</a></h1><p>本篇带你完成一张白底主图和五张各有职责的副图。沿用跨境模板里的DN01收纳盒练习，白色ABS、外尺寸220×150×120mm、盒体1、盖子1、可拆隔板1。这些是虚构填写数据，正式使用前换成你的真实商品、实拍、尺寸和清单；此处没有生成结果，也没有Amazon上传实测。</p><h2 id="_1-新建任务-先确定站点和图片位置" tabindex="-1">1. 新建任务，先确定站点和图片位置 <a class="header-anchor" href="#_1-新建任务-先确定站点和图片位置" aria-label="Permalink to &quot;1. 新建任务，先确定站点和图片位置&quot;">​</a></h2><p>在任务表写“Amazon US、商品类目、主图或副图、SKU”。读取当前类目图片要求，再确定导出参数。Amazon公开摄影指南给出纯白底、完整真实商品和占幅指导；主图的广告字、场景道具与促销标签应移除。服装等特殊类目另核对应要求。<a href="https://sell.amazon.com/blog/product-photos" target="_blank" rel="noreferrer">Amazon摄影指南</a>。</p><p>本练习选2000×2000像素方形母版，作为制作建议。不是所有模型都直接输出该像素，下载后检查实际结果，需要时在图层软件裁切或缩放。放大不会把模糊的标签还原成真实信息。</p><p>准备正面、开盖、隔板、配件平铺照片和尺寸记录。把它们对应到下面的文件计划。</p><table tabindex="0"><thead><tr><th>文件</th><th>展示内容</th><th>制作来源</th></tr></thead><tbody><tr><td>01-main</td><td>本SKU完整商品</td><td>正面真实主体＋纯白底</td></tr><tr><td>02-desk</td><td>桌面使用场景</td><td>桌面背景＋真实主体</td></tr><tr><td>03-divider</td><td>开盖与隔板</td><td>结构实拍，不补内部细节</td></tr><tr><td>04-size</td><td>外尺寸</td><td>实拍＋矢量线＋准确数字</td></tr><tr><td>05-in-box</td><td>发货内容</td><td>实际商品、盖子、隔板平铺</td></tr><tr><td>06-use</td><td>放入、收纳、合盖</td><td>对应动作实拍＋短标题</td></tr></tbody></table><h2 id="_2-白底主图-在ps或photopea操作" tabindex="-1">2. 白底主图，在PS或Photopea操作 <a class="header-anchor" href="#_2-白底主图-在ps或photopea操作" aria-label="Permalink to &quot;2. 白底主图，在PS或Photopea操作&quot;">​</a></h2><ol><li>新建2000×2000白色画布，RGB模式，背景填 <code>#FFFFFF</code>。</li><li>导入正面照片为独立商品层，选主体，添加蒙版，处理边缘。主体原像素保留，蒙版只隐藏拍摄背景。<a href="https://helpx.adobe.com/photoshop/desktop/make-selections/automatic-color-based-selections/detect-subject-using-select-subject.html" target="_blank" rel="noreferrer">PS选择主体</a>。</li><li>等比缩放，让商品完整、清楚、四边不截断。按实际类目要求检查占幅；公开指南的85%指导可用于构图参考，不能替代当前后台标准。</li><li>去掉文具、宣传贴纸、Logo装饰层、图标和标题。商品本身的真实印刷保留。用吸管检查背景角落，避免导出的是浅灰纹理底。</li><li>100%查看白色商品边缘，有残灰就改蒙版，有缺口就恢复蒙版；不要直接刷白把商品边缘吃掉。</li></ol><p>若希望用图像工具清理背景，输入下面的任务词。工具无法保持商品像素时回图层母版处理。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入是本SKU真实正面商品照片。用于Amazon商品主图，只把拍摄背景清理成纯白RGB255/255/255，保留商品原有形状、颜色、标识、盖子和可见结构。商品完整清楚，不裁切，不添加任何零件。</span></span>
<span class="line"><span>不生成标题、促销字、徽章、认证、道具或水印，不把白色ABS改成金属或陶瓷。不推测隐藏结构。若只能重绘商品而不能保留真实主体，请只输出背景处理建议，商品由原照片合成。</span></span></code></pre></div><h2 id="_3-场景副图-先解释用途" tabindex="-1">3. 场景副图，先解释用途 <a class="header-anchor" href="#_3-场景副图-先解释用途" aria-label="Permalink to &quot;3. 场景副图，先解释用途&quot;">​</a></h2><p>DN01的用途是书桌收纳文具，桌面、笔和本子只作场景背景。生成工具负责环境，盒子保不住就用真实商品层合成。不要让几支笔与收纳盒并排成“套装发货”画面。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>制作桌面收纳盒的场景副图。真实商品照片是唯一外观依据，保留白色盒体、盖子、比例和标识。明亮书桌，浅木台面，左前方柔和自然光，少量文具在背景，商品为视觉中心。</span></span>
<span class="line"><span>画面左上留简洁区域用于后期标题，不生成文字、数字、认证或水印，不改变商品材质，不添加新隔板，不画未提供的背面。场景道具不作为商品发货内容展示。如果无法保持商品身份，只生成没有盒子的空桌面背景。</span></span></code></pre></div><p>合成后在独立文字层写练习标题 <code>A place for everyday stationery</code>。它描述用途，不暗示容量、承重或安全等级。缩成手机宽度，商品比装饰更显眼、标题能读，才保留这张。</p><h2 id="_4-结构、尺寸与发货图分开做" tabindex="-1">4. 结构、尺寸与发货图分开做 <a class="header-anchor" href="#_4-结构、尺寸与发货图分开做" aria-label="Permalink to &quot;4. 结构、尺寸与发货图分开做&quot;">​</a></h2><p>结构图直接用开盖实拍。若一个隔板在照片中可拆，就用对应照片说明，不让模型凭空把内部分成六格。练习可用标题 <code>Removable divider</code>，正式文案需要真实结构依据。</p><p>尺寸图以外尺寸为准，排 <code>220 × 150 × 120 mm</code>；US版本需要英寸时，同时保留厘米或毫米，明确L×W×H与外尺寸。不要把透视角度的斜边当长度，使用能清楚看出测量方向的照片。<a href="./localization">尺寸与本地化操作</a>。</p><p>发货图用真实平铺，标题 <code>What&#39;s in the box</code>，列表 <code>1 box body / 1 lid / 1 divider</code>。文具不出现或写明不包含。没有官方认证与报告就不做认证图。</p><h2 id="_5-使用图按实际动作排三组" tabindex="-1">5. 使用图按实际动作排三组 <a class="header-anchor" href="#_5-使用图按实际动作排三组" aria-label="Permalink to &quot;5. 使用图按实际动作排三组&quot;">​</a></h2><p>第一组打开盒盖，第二组放入与商品用途一致的文具，第三组合盖。动作图用实拍或经逐项核对的结果，手和盒子的接触关系不能错。没有动作照片时，这张先用产品结构说明替代，别编一个“自动开盖”功能。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据本商品的真实使用说明和动作照片整理三组副图文案。每组输出准确短标题、对应照片、阅读顺序和必须看清的操作部位。只保留资料支持的打开、放入、合盖动作，缺失步骤标待补拍。不要生成产品结构、手部动作或未经确认的功能。文案供后期文字层排版。</span></span></code></pre></div><h2 id="_6-导出、排顺序与返工" tabindex="-1">6. 导出、排顺序与返工 <a class="header-anchor" href="#_6-导出、排顺序与返工" aria-label="Permalink to &quot;6. 导出、排顺序与返工&quot;">​</a></h2><p>每张保留PSD或等效源文件，另导出JPG。练习命名 <code>DN01_white_amazon-us_01-main_en_v01.jpg</code>，依次到06。重新打开检查像素、边缘、颜色和文字，按计划排序；实际上传后再看商品页缩略图、放大图、变体与手机裁切。</p><table tabindex="0"><thead><tr><th>发现的问题</th><th>回到哪里改</th></tr></thead><tbody><tr><td>主图背景发灰</td><td>第2步填纯白并检查导出</td></tr><tr><td>主图多了文具</td><td>第2步移除道具层，核发货清单</td></tr><tr><td>场景图变成另一个盒型</td><td>第3步只生成背景，放回真实主体</td></tr><tr><td>结构图多出隔板</td><td>第4步用开盖实拍重新排版</td></tr><tr><td>文字太长读不清</td><td>删次要句，拆两张副图，保持准确参数</td></tr><tr><td>变体白图对应灰色SKU</td><td>修媒体对应和文件名，不能只换名字</td></tr></tbody></table><p>完成后进入<a href="./amazon-a-plus">A+模块</a>。通用白底任务模板见<a href="./../prompts/P10">P10</a>，副图职责模板见<a href="./../prompts/P11">P11</a>，本篇已给直接可复制的制作词。</p>`,26)])])}const b=a(s,[["render",i]]);export{m as __pageData,b as default};
